class Solution {
  public long maximumScore(int[] nums, String s) {
    java.util.PriorityQueue<Integer> heap =
        new java.util.PriorityQueue<>(java.util.Collections.reverseOrder());
    long score = 0;
    for (int i = 0; i < nums.length; i++) {
      heap.add(nums[i]);
      if (s.charAt(i) == '1') score += heap.poll();
    }
    return score;
  }
}
